<?php foreach($series as $type=>$color):$points=[];foreach($chartRows as $row){if($row['value_type']!==$type)continue;$x=80+535*(strtotime($row['as_of_date'].' UTC')-$minDate)/max(86400,$maxDate-$minDate);$y=175-150*(float)$row['amount']/$maxAmount;$points[]=round($x,2).','.round($y,2);}if(!$points)continue;?><polyline points="<?= implode(' ',$points) ?>" fill="none" stroke="<?= $color ?>" stroke-width="2"/><?php foreach($points as $point):[$x,$y]=explode(',',$point);?><circle cx="<?= $x ?>" cy="<?= $y ?>" r="3" fill="<?= $color ?>"/><?php endforeach;endforeach;?></svg><div class="chart-legend"><?php foreach($series as $type=>$color):?><span><i style="background:<?= $color ?>"></i><?= e(str_replace('_',' ',$type)) ?></span><?php endforeach;?></div></figure>
<details class="settings-form"><summary>Value observations and sources (<?= count($history) ?>)</summary><div class="table-wrap"><table><thead><tr><th>Date</th><th>Value type</th><th>Amount</th><th>Source</th></tr></thead><tbody><?php foreach(array_reverse($history) as $snapshot):?><tr><td><?= e($snapshot['as_of_date']) ?></td><td><?= e($snapshot['value_type']) ?></td><td><?= e($money($snapshot['amount'])) ?></td><td><?= e($snapshot['source_type']) ?><small><?= e($snapshot['source_detail']) ?></small></td></tr><?php endforeach;?></tbody></table></div></details><?php else:?><p class="empty-inline">Save a depreciation profile or record an external value to start the history.</p><?php endif;?>
<?php if($canEdit):?><details class="settings-form"><summary><?= $profile?'Edit':'Set up' ?> straight-line depreciation</summary><form action="equipment-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="depreciation"><input type="hidden" name="id" value="<?= e($id) ?>"><?php foreach(['acquisition_cost'=>'Acquisition cost','salvage_value'=>'Salvage value','useful_life_years'=>'Useful life (years)'] as $key=>$label):?><label><?= $label ?><input name="<?= $key ?>" type="number" min="<?= $key==='useful_life_years'?'0.001':'0' ?>" step="<?= $key==='useful_life_years'?'0.001':'0.01' ?>" value="<?= e((string)($profile[$key]??($key==='salvage_value'?'0':''))) ?>" required></label><?php endforeach;?><label>Currency<input name="currency" value="<?= e($currency) ?>" pattern="[A-Za-z]{3}" maxlength="3" required></label><label>Acquisition date<input type="date" name="acquisition_date" value="<?= e($profile['acquisition_date']??'') ?>" required></label><label>Depreciation start date <small>Defaults to acquisition date</small><input type="date" name="start_date" value="<?= e($profile['start_date']??'') ?>"></label><label class="check-label full"><input type="checkbox" name="is_active" <?= !$profile||$profile['is_active']?'checked':'' ?>> Active depreciation profile</label><label class="full">Notes<textarea name="notes" maxlength="20000"><?= e($profile['notes']??'') ?></textarea></label><p class="full">Annual depreciation = (cost − salvage) ÷ useful life. Book value never falls below salvage. Turning off the profile pauses calculations; prior snapshots remain intact.</p><div class="full"><button class="primary">Save depreciation profile</button></div></form></details>
<details class="settings-form"><summary>Record a market value or externally supplied AI estimate</summary><p>Enter a value you already obtained. This form does not generate an AI valuation.</p><form action="equipment-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="value"><input type="hidden" name="id" value="<?= e($id) ?>"><label>Value type<select name="value_type"><option value="MARKET">Market value</option><option value="MARKET_ESTIMATE_AI">AI market estimate</option><option value="BOOK_ESTIMATE_AI">AI book estimate</option></select></label><label>Source type<select name="source_type"><option value="USER">User observation</option><option value="EXTERNAL_API">External API</option><option value="AI_AGENT">AI agent</option></select></label><label>Amount (<?= e($currency) ?>)<input name="amount" type="number" min="0" step="0.01" required></label><label>As-of date<input name="as_of_date" type="date" max="<?= gmdate('Y-m-d') ?>" value="<?= gmdate('Y-m-d') ?>" required></label><label class="full">Source details / model / reference<textarea name="source_detail" maxlength="20000" required></textarea></label><div class="full"><button class="primary">Record value observation</button></div></form></details><?php endif;?></section>
