<?php if(!$assemblies):?><p class="empty-inline">No assemblies have been installed. Classify this asset by equipment type to load matching templates, or add a custom assembly.</p><?php endif;?>
<?php $assemblyNames=array_column($assemblies,'name','id');foreach($assemblies as $assembly):$installed=rows('SELECT i.*,p.name AS part_name,p.unit_of_measure FROM equipment_assembly_items i LEFT JOIN part_master p ON p.id=i.part_id WHERE i.equipment_assembly_id=? ORDER BY i.sequence,i.installed_at,i.id',[$assembly['id']]);?><details class="settings-form" open><summary><?= e(($assembly['parent_assembly_id']?($assemblyNames[$assembly['parent_assembly_id']].' / '):'').$assembly['name']) ?> <span class="muted"><?= $assembly['is_custom_addon']?'Custom add-on':'From template' ?></span></summary><p><?= e($assembly['description']??'') ?></p><div class="table-wrap"><table><thead><tr><th>Part / slot</th><th>Quantity</th><th>Installation</th><th></th></tr></thead><tbody><?php foreach($installed as $item):?><tr><td><?= e($item['part_name']??$item['custom_name']) ?><small><?= $item['is_custom_addon']?'Custom / asset-specific':'Template part' ?></small></td><td><?= e($item['quantity'].' '.($item['unit_of_measure']??'')) ?></td><td><?= e($item['status']??'Not recorded') ?><small><?= e($item['installed_at']??'Not installed') ?><?= $item['removed_at']?' · Removed '.e($item['removed_at']):'' ?></small></td><td><?php if($canEdit&&!$item['removed_at']&&$item['installed_at']):?><form action="equipment-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="part.remove"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="hidden" name="item_id" value="<?= e($item['id']) ?>"><button class="text-button">Mark removed</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php if($canEdit):?><form action="equipment-action" method="post" class="form-grid mini-form"><?= csrf_field() ?><input type="hidden" name="action" value="part.add"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="hidden" name="equipment_assembly_id" value="<?= e($assembly['id']) ?>"><label>Canonical part<select name="part_id"><option value="">Use a custom name</option><?php foreach($catalog['part'] as $part):?><option value="<?= e($part['id']) ?>"><?= e($part['name']) ?></option><?php endforeach;?></select></label><label>Custom part name <small>Required if no canonical part</small><input name="custom_name" maxlength="255"></label><label>Quantity<input type="number" name="quantity" min="0.001" step="0.001" value="1" required></label><label>Display order<input type="number" name="sequence" value="0"></label><div class="full"><button class="secondary">Install part / add-on</button></div></form><?php endif;?></details><?php endforeach;?>
<?php if($canEdit):?><details class="settings-form"><summary>Add custom assembly</summary><form action="equipment-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="assembly.add"><input type="hidden" name="id" value="<?= e($id) ?>"><label>Assembly name<input name="name" maxlength="255" required></label><label>Display order<input name="sequence" type="number" value="0"></label><label class="full">Description<textarea name="description" maxlength="20000"></textarea></label><div class="full"><button class="primary">Add assembly</button></div></form></details><form action="equipment-action" method="post" class="section-gap"><?= csrf_field() ?><input type="hidden" name="action" value="templates.load"><input type="hidden" name="id" value="<?= e($id) ?>"><button class="secondary">Load missing matching templates</button><p>Existing assemblies and installed quantities are preserved.</p></form><?php endif;?></section>
<section class="panel settings-section" id="equipment-documentation"><h2>Documentation &amp; certification</h2><p>No document management integration is available for this equipment yet.</p></section>
<section class="panel settings-section" id="equipment-lease"><h2>Lease</h2><p>No lease records are available for this equipment.</p></section>
<?php if($canEdit):?><section class="panel settings-section" id="equipment-archive"><h2>Archive equipment</h2><p>Remove this asset from the active register and KPI totals. Its photos, maintenance records, values, and audit history will be retained. Open maintenance and active alerts must be resolved first.</p><form action="equipment-action" method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?= e($id) ?>"><label>Type the asset ID to confirm: <?= e($record['asset_code']) ?><input name="confirmation" maxlength="100" autocomplete="off" required></label><div class="full"><button class="secondary">Archive equipment</button></div></form></section><?php endif;?>
